from itertools import product
from math import gcd

# Partitions are decreasing tuples of positive integers; () is empty.
def parts(max_part, max_len, max_sum=None):
    out=[]
    def rec(last, k, cur):
        out.append(tuple(cur))
        if k==max_len: return
        for x in range(min(last, max_part),0,-1):
            if max_sum is None or sum(cur)+x<=max_sum:
                rec(x,k+1,cur+[x])
    rec(max_part,0,[])
    return out

def contains(nu, mu):
    return all((nu[t] if t<len(nu) else 0) >= x for t,x in enumerate(mu))
def size(p): return sum(p)

def lr(lam, mu, nu):
    # Enumerate LR tableaux of skew nu/mu, content lam, with row weak/column strict
    if size(lam)+size(mu)!=size(nu) or not contains(nu,mu): return 0
    cells=[]
    for r,n in enumerate(nu, start=1):
        m=mu[r-1] if r<=len(mu) else 0
        for c in range(m+1,n+1): cells.append((r,c))
    # reading order: right-to-left, top-to-bottom. At insertion, right neighbor and above known.
    tab={}; used=[0]*(len(lam)+1); ans=0
    def rec(k):
        nonlocal ans
        if k==len(cells): ans+=1; return
        r,c=cells[k]
        right=tab.get((r,c+1))
        above=tab.get((r-1,c))
        for v in range(1,len(lam)+1):
            if used[v]>=lam[v-1]: continue
            # weak rows left-to-right, so current <= right
            if right is not None and v>right: continue
            # strict columns top-to-bottom, so current > above
            if above is not None and v<=above: continue
            used[v]+=1
            # lattice/Yamanouchi condition on every reading prefix
            good=all(used[t]>=used[t+1] for t in range(1,len(lam)))
            if good:
                tab[(r,c)]=v; rec(k+1); del tab[(r,c)]
            used[v]-=1
    rec(0); return ans

def egcd(a,b):
    if b==0: return (abs(a), 1 if a>0 else -1 if a<0 else 1, 0)
    g,x1,y1=egcd(b,a%b); return g,y1,x1-(a//b)*y1

def smith(A):
    # elementary unimodular operations, returns diagonal (signs normalized)
    A=[row[:] for row in A]; m=len(A); n=len(A[0]) if m else 0; k=0
    def rswap(i,j): A[i],A[j]=A[j],A[i]
    def cswap(i,j):
        for row in A: row[i],row[j]=row[j],row[i]
    def radd(i,j,q): A[i]=[x+q*y for x,y in zip(A[i],A[j])]
    def cadd(i,j,q):
        for row in A: row[i]+=q*row[j]
    while k<m and k<n:
        pos=None
        for i in range(k,m):
            for j in range(k,n):
                if A[i][j]:
                    if pos is None or abs(A[i][j])<abs(A[pos[0]][pos[1]]): pos=(i,j)
        if pos is None: break
        rswap(k,pos[0]); cswap(k,pos[1])
        while True:
            changed=False
            # Euclidean clearing in column/row
            for i in range(k+1,m):
                if A[i][k]:
                    q=A[i][k]//A[k][k]; radd(i,k,-q)
                    if abs(A[i][k])<abs(A[k][k]) and A[i][k]: rswap(i,k)
                    changed=True; break
            if changed: continue
            for j in range(k+1,n):
                if A[k][j]:
                    q=A[k][j]//A[k][k]; cadd(j,k,-q)
                    if abs(A[k][j])<abs(A[k][k]) and A[k][j]: cswap(j,k)
                    changed=True; break
            if changed: continue
            # if pivot does not divide remaining block, add offending row to pivot row
            bad=None
            for i in range(k+1,m):
                for j in range(k+1,n):
                    if A[i][j]%A[k][k]: bad=(i,j); break
                if bad: break
            if bad:
                radd(k,bad[0],1); changed=True; continue
            break
        if A[k][k]<0: A[k]=[-x for x in A[k]]
        k+=1
    return [A[i][i] for i in range(min(m,n)) if A[i][i]!=0]

def run(r,q,i,j):
    B=parts(q,r)
    rho=(i,)*j
    U=[p for p in B if contains(p,rho)]
    L=[p for p in B if p]
    # columns generators U; each product yields one relation row
    rows=[]
    for lam in L:
        for mu in U:
            row=[]
            for nu in U: row.append(lr(lam,mu,nu))
            if any(row): rows.append(row)
    D=smith(rows)
    rank=len(D); free=len(U)-rank
    tors=[d for d in D if d>1]
    print({'r':r,'q':q,'i':i,'j':j,'U':len(U),'relations':len(rows),
           'SNF_nonzero_diagonal':D,'free_rank':free,'torsion_invariants':tors})
run(2,6,1,1)
run(5,2,1,1)
